def parse_orders(text):
    lines = [l for l in text.strip().splitlines() if l.strip()]
    out = []
    for l in lines[1:]:
        parts = l.split(',')
        out.append((parts[0], int(parts[1])))  # BUG: qty may be '12 units'
    return out

def total(text):
    return sum(q for _, q in parse_orders(text))

